'use strict';
const MISSIONS = [
 {id:'apollo',name:'Apollo 17 rover',kind:'Lunar Roving Vehicle',world:'moon',years:'1972',place:'Taurus–Littrow',status:'Parked on the Moon',image:'lunar-rover.svg',headline:'The last parking spot.',number:'01',facts:[['DESTINATION','The Moon'],['MISSION','Apollo 17 · 1972'],['LEFT BEHIND','Lunar rover']],story:'For three excursions, an electric rover helped Gene Cernan and Harrison Schmitt explore the Taurus–Littrow valley. Before departing, Cernan drove it to a final parking spot about 158 metres from the lunar module. Its television camera watched the astronauts lift off.',legacy:'The rover could not come home. It remains on the Moon, alongside the descent stage and equipment from the mission. The tracks are a record of where people went—and the samples they collected still give scientists new questions to ask.',timeline:[['7 Dec 1972','Launch from Earth'],['11 Dec 1972','Lunar landing'],['14 Dec 1972','Crew leaves the Moon']],source:'https://www.nasa.gov/history/50-years-ago-apollo-17-lands-at-taurus-littrow/',sourceLabel:'NASA · Apollo 17 at Taurus–Littrow'},
 {id:'opportunity',name:'Opportunity',kind:'Mars Exploration Rover · MER-B',world:'mars',years:'2004—2018',place:'Perseverance Valley',status:'Last contact: June 2018',image:'mars-rover.svg',headline:'A short mission. An extraordinary life.',number:'02',facts:[['DESTINATION','Mars'],['DISTANCE','45.16 kilometres'],['LAST SIGNAL','10 June 2018']],story:'Opportunity arrived with a planned prime mission of 90 Martian days. It kept exploring for more than 14 Earth years, following clues to a wetter Mars across 45.16 kilometres of terrain. Then a planet-wide dust storm darkened the sky and cut its solar power.',legacy:'Its final signal reached Earth on 10 June 2018. Recovery attempts continued until NASA declared the mission complete in February 2019. The rover remains in Perseverance Valley. Its observations helped establish that ancient Mars had environments that could have supported microbial life—not that life was found.',timeline:[['July 2003','Launched from Earth'],['January 2004','Arrived on Mars'],['June 2018','Final communication']],source:'https://science.nasa.gov/mission/mer-opportunity/',sourceLabel:'NASA Science · Opportunity'},
 {id:'surveyor',name:'Surveyor 3',kind:'Robotic lunar lander',world:'moon',years:'1967',place:'Oceanus Procellarum',status:'Visited by Apollo 12',image:'surveyor.svg',headline:'The explorer we went back to.',number:'03',facts:[['DESTINATION','The Moon'],['LANDED','20 April 1967'],['VISITED','November 1969']],story:'Before people stepped onto the Moon, Surveyor 3 tested its soil and sent back thousands of television images. Its sampler helped establish that the ground could support an Apollo lunar module. Contact ended on 4 May 1967.',legacy:'In November 1969, Apollo 12 astronauts walked to the silent lander. They removed its camera and other parts for study on Earth. The rest stayed behind. Surveyor 3 became a rare case of humans revisiting a robotic explorer on another world.',timeline:[['17 Apr 1967','Launch'],['20 Apr 1967','Soft landing'],['Nov 1969','Apollo 12 visit']],source:'https://science.nasa.gov/mission/surveyor-3/',sourceLabel:'NASA Science · Surveyor 3'},
 {id:'spirit',name:'Spirit',kind:'Mars Exploration Rover · MER-A',world:'mars',years:'2004—2010',place:'Gusev crater',status:'Silent since March 2010',image:'spirit.svg',headline:'Even a broken wheel found a way.',number:'04',facts:[['DESTINATION','Mars'],['DISTANCE','7.73 kilometres'],['OPERATIONS','More than six years']],story:'Spirit explored Mars alongside its twin, Opportunity. A dragging wheel unexpectedly uncovered silica-rich soil—evidence consistent with ancient hot springs or steam vents. A mechanical problem had become a scientific opportunity.',legacy:'After becoming stuck in soft soil, Spirit continued working from one place. It fell silent in March 2010, and NASA ended recovery efforts in May 2011. The rover remains at Gusev crater, while its discoveries continue to shape our understanding of a once-wetter Mars.',timeline:[['June 2003','Launched from Earth'],['January 2004','Arrived at Gusev'],['May 2011','Mission declared complete']],source:'https://science.nasa.gov/mission/mer-spirit/',sourceLabel:'NASA Science · Spirit'},
 {id:'viking',name:'Viking 1',kind:'Mars lander',world:'mars',years:'1976—1982',place:'Chryse Planitia',status:'Mission complete',image:'viking.svg',headline:'A new world, at ground level.',number:'05',facts:[['DESTINATION','Mars'],['LANDED','20 July 1976'],['LANDER','Stationary laboratory']],story:'Viking 1 brought the Martian surface into focus from a fixed landing site. Its cameras, weather instruments, and biology experiments made the lander a laboratory on another planet, paired with an orbiter overhead.',legacy:'The lander operated until November 1982, far beyond its original mission. Its biology experiments did not establish that life existed on Mars. Viking’s results helped define the questions that later missions would pursue. The lander remains in Chryse Planitia.',timeline:[['August 1975','Launch'],['July 1976','Lander reaches Mars'],['November 1982','Lander communication ends']],source:'https://science.nasa.gov/mission/viking-1/',sourceLabel:'NASA Science · Viking 1'},
 {id:'insight',name:'InSight',kind:'Mars geophysical lander',world:'mars',years:'2018—2022',place:'Elysium Planitia',status:'Mission complete',image:'insight.svg',headline:'It stayed still. And looked deeper.',number:'06',facts:[['DESTINATION','Mars'],['LANDED','26 November 2018'],['PURPOSE','Study the interior']],story:'InSight did not need to drive. From Elysium Planitia, it placed instruments on the ground and listened for seismic activity. By recording marsquakes, it helped scientists investigate the structure hidden beneath the surface.',legacy:'Dust on the solar panels gradually reduced the power available to the lander, and the mission ended in December 2022. Its instruments remain on Mars. The measurements it returned continue to offer a way to look inside a planet we have barely touched.',timeline:[['May 2018','Launch'],['November 2018','Mars landing'],['December 2022','Mission ends']],source:'https://science.nasa.gov/mission/insight/',sourceLabel:'NASA Science · InSight'}
];
const CHAPTERS=[
 {year:'1967',tag:'SURVEYOR 3 / THE MOON',title:'Before the<br>first footsteps.',body:'A robotic scout tested the ground before astronauts arrived. Two years later, Apollo 12 visited Surveyor 3 and brought parts of it home.',id:'surveyor'},
 {year:'1972',tag:'APOLLO 17 / THE MOON',title:'One last drive.<br>One giant legacy.',body:'The crew went home. Their rover stayed. Parked near the lunar module, its camera watched the ascent stage carry two explorers back toward Earth.',id:'apollo'},
 {year:'2004',tag:'SPIRIT & OPPORTUNITY / MARS',title:'Two rovers.<br>A wetter past.',body:'On opposite sides of Mars, twin explorers began a search for clues to ancient water. Both outlived their planned 90-sol prime missions by years.',id:'opportunity'},
 {year:'2018',tag:'INSIGHT / MARS',title:'A quiet place.<br>A deeper story.',body:'A new lander began listening to the planet itself. InSight recorded seismic activity from a single site, opening a window into the interior of Mars.',id:'insight'}
];
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
let filter='all',chapter=-1,returnFocus=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
window.explorerMotion={paused:reduced.matches};
function renderArchive(){
 const query=$('#search').value.trim().toLowerCase();
 const list=MISSIONS.filter(m=>(filter==='all'||m.world===filter)&&`${m.name} ${m.kind} ${m.world} ${m.years} ${m.place}`.toLowerCase().includes(query));
 $('#archive-list').innerHTML=list.map(m=>`<button class="archive-row" data-mission="${m.id}" aria-label="Read ${m.name} story"><span class="number">${m.number}</span><span class="archive-thumb"><img src="assets/${m.image}" alt="" loading="lazy"></span><span class="archive-name"><h3>${m.name}</h3><span>${m.kind}</span></span><span class="archive-destination">${m.world==='moon'?'◐ MOON':'◉ MARS'}</span><span class="archive-date">${m.years}</span><span class="archive-arrow" aria-hidden="true">↗</span></button>`).join('');
 $('#empty-state').hidden=list.length!==0;
 $('#result-count').textContent=`${list.length} explorer${list.length===1?'':'s'} found`;
}
function setFilter(value){filter=value;$$('[data-filter]').forEach(b=>{let on=b.dataset.filter===value;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)});renderArchive()}
function openMission(id){
 const m=MISSIONS.find(m=>m.id===id);if(!m)return;
 returnFocus=document.activeElement;
 const next=MISSIONS[(MISSIONS.indexOf(m)+1)%MISSIONS.length];
 $('#dialog-content').innerHTML=`<div class="dialog-hero"><img src="assets/${m.image}" alt="Artistic interpretation of ${m.name}"><span>ARTIST’S INTERPRETATION · NOT AN ENGINEERING MODEL</span></div><div class="dialog-main"><p class="eyebrow">EXPLORER ${m.number} / ${m.world.toUpperCase()} / ${m.years}</p><h2 id="dialog-title">${m.name}</h2><p class="dialog-subtitle">${m.headline}</p><dl class="mission-facts">${m.facts.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><div class="story-columns"><div><h3>The mission.</h3><p>${m.story}</p></div><div><h3>What remains.</h3><p>${m.legacy}</p></div></div><div class="mission-timeline">${m.timeline.map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="dialog-actions"><a class="pill" href="${m.source}" target="_blank" rel="noopener noreferrer">Read the NASA record <span>↗</span></a><button class="text-link" data-next="${next.id}">Next: ${next.name} <span>→</span></button></div></div>`;
 if(!$('#mission-dialog').open)$('#mission-dialog').showModal();
 document.body.classList.add('locked');$('#mission-dialog').scrollTop=0;
 $('#mission-dialog .dialog-close').focus({preventScroll:true});
}
function closeDialog(d){d.close()}
$$('dialog').forEach(d=>{
 d.querySelector('.dialog-close').addEventListener('click',()=>closeDialog(d));
 d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}});
 d.addEventListener('close',()=>{if(!$('#menu').hidden)return;document.body.classList.remove('locked');returnFocus?.focus({preventScroll:true})});
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-mission]');if(b)openMission(b.dataset.mission);const n=e.target.closest('[data-next]');if(n){const old=returnFocus;openMission(n.dataset.next);returnFocus=old}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));
$('#search').addEventListener('input',renderArchive);
$('#clear-search').addEventListener('click',()=>{$('#search').value='';setFilter('all');$('#search').focus()});
$('#source-list').innerHTML=MISSIONS.map(m=>`<a href="${m.source}" target="_blank" rel="noopener noreferrer">${m.sourceLabel} <span>↗</span></a>`).join('');
$('#sources-button').addEventListener('click',()=>{returnFocus=document.activeElement;$('#sources-dialog').showModal();document.body.classList.add('locked')});
function toggleMenu(force){const open=typeof force==='boolean'?force:$('#menu').hidden;$('#menu').hidden=!open;$('.menu-control').setAttribute('aria-expanded',open);document.body.classList.toggle('menu-open',open);document.body.classList.toggle('locked',open);if(open)$('#menu a').focus();else $('.menu-control').focus({preventScroll:true})}
$('.menu-control').addEventListener('click',()=>toggleMenu());
$$('#menu a').forEach(a=>a.addEventListener('click',()=>toggleMenu(false)));
document.addEventListener('keydown',e=>{if($('#menu').hidden)return;if(e.key==='Escape')toggleMenu(false);if(e.key==='Tab'){const links=[$('.menu-control'),...$$('#menu a')];let i=links.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();links.at(-1).focus()}else if(!e.shiftKey&&i===links.length-1){e.preventDefault();links[0].focus()}}});
function setMotion(paused){window.explorerMotion.paused=paused;document.documentElement.classList.toggle('is-paused',paused);$('.motion-control').setAttribute('aria-pressed',paused);$('.motion-control').setAttribute('aria-label',paused?'Play animation':'Pause animation');$('.motion-control span').textContent=paused?'▶':'Ⅱ';window.dispatchEvent(new Event('motionchange'))}
$('.motion-control').addEventListener('click',()=>setMotion(!window.explorerMotion.paused));reduced.addEventListener('change',e=>setMotion(e.matches));setMotion(reduced.matches);
function setChapter(i){if(chapter===i)return;chapter=i;const c=CHAPTERS[i];$('#chapter-year').textContent=c.year;$('#chapter-tag').textContent=c.tag;$('#chapter-title').innerHTML=c.title;$('#chapter-body').textContent=c.body;$('#chapter-link').dataset.mission=c.id;$('#chapter-count').textContent=`0${i+1} / 04`;$('.journey-track>span').style.width=`${(i+1)*25}%`;$$('[data-chapter]').forEach((b,n)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-pressed',i===n)})}
$$('[data-chapter]').forEach(b=>b.addEventListener('click',()=>{const i=+b.dataset.chapter;setChapter(i);if(!reduced.matches&&!window.explorerMotion.paused){const section=$('#journey'),travel=Math.max(0,section.offsetHeight-innerHeight);window.scrollTo({top:section.offsetTop+travel*((i+.15)/4),behavior:'smooth'})}}));
let ticking=false;
function scrollUpdate(){ticking=false;const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.transform=`scaleX(${max>0?scrollY/max:0})`;const section=$('#journey'),r=section.getBoundingClientRect();if(!reduced.matches&&!window.explorerMotion.paused&&r.top<=0&&r.bottom>=innerHeight){const progress=-r.top/Math.max(1,section.offsetHeight-innerHeight);setChapter(Math.min(3,Math.floor(progress*4)))}if(!window.explorerMotion.paused){const p=Math.min(1,scrollY/innerHeight);$('.hero-title').style.transform=`translateY(${p*60}px)`;$('.orbital-line').style.transform=`rotate(${-23+p*30}deg) scale(${1+p*.15})`}}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollUpdate);ticking=true}},{passive:true});addEventListener('resize',scrollUpdate);
$$('[data-world]').forEach(b=>b.addEventListener('click',()=>{$$('[data-world]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on)});const mars=b.dataset.world==='mars';$('#planet-code').textContent=mars?'DESTINATION 02 / MARS':'DESTINATION 01 / MOON';$('#planet-caption').textContent=mars?'A planet full of possibilities.':'A world that remembers.';$('.planet-fallback').style.filter=mars?'sepia(1) saturate(2) hue-rotate(330deg)':'none';window.dispatchEvent(new CustomEvent('worldchange',{detail:b.dataset.world}))}));
renderArchive();setChapter(0);scrollUpdate();
if('IntersectionObserver' in window){document.documentElement.classList.add('js-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(e=>observer.observe(e))}
